```yaml
name: Deploy Landing Page to GitHub Pages

on:
  push:
    branches:
      - main
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: "pages"
  cancel-in-progress: false

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Create Landing Page
        run: |
          mkdir -p docs
          cat > docs/index.html << 'EOF'
          <!DOCTYPE html>
          <html lang="en">
          <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Dr. Manhattan | Quantum Data Analysis</title>
            <style>
              :root {
                --bg-color: #050510;
                --card-bg: #0a0a1a;
                --text-primary: #e0e0ff;
                --text-secondary: #8888aa;
                --accent-blue: #00f0ff;
                --accent-glow: rgba(0, 240, 255, 0.3);
                --border-color: #1a1a3a;
              }

              * {
                box-sizing: border-box;
                margin: 0;
                padding: 0;
              }

              body {
                font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                background-color: var(--bg-color);
                color: var(--text-primary);
                line-height: 1.6;
                overflow-x: hidden;
              }

              /* Cosmic Background Effect */
              body::before {
                content: '';
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                background: 
                  radial-gradient(circle at 20% 30%, rgba(0, 240, 255, 0.05) 0%, transparent 40%),
                  radial-gradient(circle at 80% 70%, rgba(100, 0, 255, 0.05) 0%, transparent 40%);
                z-index: -1;
                pointer-events: none;
              }

              .container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 0 20px;
              }

              /* Header */
              header {
                padding: 40px 0;
                text-align: center;
                border-bottom: 1px solid var(--border-color);
              }

              h1 {
                font-size: 3rem;
                font-weight: 700;
                margin-bottom: 10px;
                background: linear-gradient(90deg, #fff, var(--accent-blue));
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                text-shadow: 0 0 20px var(--accent-glow);
              }

              .subtitle {
                color: var(--text-secondary);
                font-size: 1.2rem;
                margin-bottom: 30px;
              }

              /* Install Section */
              .install-section {
                background: var(--card-bg);
                border: 1px solid var(--border-color);
                border-radius: 12px;
                padding: 20px;
                margin: 40px auto;
                max-width: 600px;
                display: flex;
                align-items: center;
                justify-content: space-between;
                box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
              }

              .install-command {
                font-family: 'Courier New', Courier, monospace;
                background: #000;
                padding: 10px 15px;
                border-radius: 6px;
                color: var(--accent-blue);
                font-size: 1rem;
                border: 1px solid #333;
              }

              .copy-btn {
                background: transparent;
                border: 1px solid var(--accent-blue);
                color: var(--accent-blue);
                padding: 8px 16px;
                border-radius: 6px;
                cursor: pointer;
                transition: all 0.3s ease;
                margin-left: 10px;
                font-weight: 600;
              }

              .copy-btn:hover {
                background: var(--accent-blue);
                color: #000;
                box-shadow: 0 0 15px var(--accent-glow);
              }

              /* Features Grid */
              .features {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 30px;
                margin: 60px 0;
              }

              .feature-card {
                background: var(--card-bg);
                border: 1px solid var(--border-color);
                border-radius: 12px;
                padding: 30px;
                transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
                position: relative;
                overflow: hidden;
              }

              .feature-card:hover {
                transform: translateY(-5px);
                box-shadow: 0 10px 30px rgba(0, 240, 255, 0.1);
                border-color: var(--accent-blue);
              }

              .feature-card::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 2px;
                background: linear-gradient(90deg, transparent, var(--accent-blue), transparent);
                transform: scaleX(0);
                transition: transform 0.3s ease;
              }

              .feature-card:hover::before {
                transform: scaleX(1);
              }

              .feature-icon {
                font-size: 2rem;
                margin-bottom: 15px;
                color: var(--accent-blue);
              }

              .feature-title {
                font-size: 1.25rem;
                margin-bottom: 10px;
                color: #fff;
              }

              .feature-desc {
                color: var(--text-secondary);
                font-size: 0.95rem;
              }

              /* Code Example */
              .code-section {
                margin: 60px 0;
              }

              .code-block {
                background: #0d0d1a;
                border: 1px solid var(--border-color);
                border-radius: 12px;
                padding: 20px;
                overflow-x: auto;
                font-family: 'Courier New', Courier, monospace;
                font-size: 0.9rem;
                position: relative;
              }

              .code-block code {
                color: #a9b7c6;
              }

              .keyword { color: #cc7832; }
              .string { color: #6a8759; }
              .function { color: #ffc66d; }
              .comment { color: #555555; font-style: italic; }

              /* Exchange Logos */
              .exchanges {
                text-align: center;
                margin: 60px 0;
                padding: 40px 0;
                border-top: 1px solid var(--border-color);
              }

              .exchanges h2 {
                margin-bottom: 30px;
                color: var(--text-secondary);
                font-weight: 400;
                text-transform: uppercase;
                letter-spacing: 2px;
                font-size: 0.9rem;
              }

              .logo-grid {
                display: flex;
                justify-content: center;
                flex-wrap: wrap;
                gap: 40px;
                opacity: 0.6;
              }

              .logo-item {
                font-size: 1.5rem;
                font-weight: bold;
                color: var(--text-secondary);
                transition: color 0.3s ease, opacity 0.3s ease;
              }

              .logo-item:hover {
                color: var(--accent-blue);
                opacity: 1;
              }

              /* Footer */
              footer {
                text-align: center;
                padding: 40px 0;
                color: var(--text-secondary);
                font-size: 0.9rem;
                border-top: 1px solid var(--border-color);
                margin-top: 40px;
              }

              a {
                color: var(--accent-blue);
                text-decoration: none;
              }

              a:hover {
                text-decoration: underline;
              }

              @media (max-width: 768px) {
                h1 { font-size: 2rem; }
                .install-section { flex-direction: column; gap: 15px; }
                .copy-btn { margin-left: 0; width: 100%; }
              }
            </style>
          </head>
          <body>
            <div class="container">
              <header>
                <h1>Dr. Manhattan</h1>
                <p class="subtitle">Quantum-powered data analysis for the modern developer</p>
              </header>

              <div class="install-section">
                <div class="install-command">pip install dr-manhattan</div>
                <button class="copy-btn" onclick="copyCommand()">Copy</button>
              </div>

              <div class="features">
                <div class="feature-card">
                  <div class="feature-icon">⚛️</div>
                  <h3 class="feature-title">Quantum Processing</h3>
                  <p class="feature-desc">Leverage quantum-inspired algorithms for faster data processing and analysis.</p>
                </div>
                <div class="feature-card">
                  <div class="feature-icon">📊</div>
                  <h3 class="feature-title">Real-time Analytics</h3>
                  <p class="feature-desc">Monitor and analyze data streams in real-time with minimal latency.</p>
                </div>
                <div class="feature-card">
                  <div class="feature-icon">🔒</div>
                  <h3 class="feature-title">Secure by Design</h3>
                  <p class="feature-desc">Enterprise-grade security features built into every layer of the stack.</p>
                </div>
              </div>

              <div class="code-section">
                <h2 style="margin-bottom: 20px; color: #fff;">Quick Start</h2>
                <div class="code-block">
                  <code>
                    <span class="keyword">import</span> dr_manhattan <span class="keyword">as</span> dm<br><br>
                    <span class="comment"># Initialize the quantum engine</span><br>
                    engine = dm.<span class="function">QuantumEngine</span>(<br>
                    &nbsp;&nbsp;mode=<span class="string">"hybrid"</span>,<br>
                    &nbsp;&nbsp;workers=<span class="string">4</span><br>
                    )<br><br>
                    <span class="comment"># Load and process dataset</span><br>
                    data = engine.<span class="function">load</span>(<span class="string">"dataset.csv"</span>)<br>
                    result = data.<span class="function">analyze</span>(<br>
                    &nbsp;&nbsp;method=<span class="string">"quantum_clustering"</span><br>
                    )<br><br>
                    <span class="keyword">print</span>(result.<span class="function">summary</span>())
                  </code>
                </div>
              </div>

              <div class="exchanges">
                <h2>Supported Exchanges</h2>
                <div class="logo-grid">
                  <div class="logo-item">Binance</div>
                  <div class="logo-item">Coinbase</div>
                  <div class="logo-item">Kraken</div>
                  <div class="logo-item">Bybit</div>
                  <div class="logo-item">OKX</div>
                </div>
              </div>

              <footer>
                <p>© 2024 Dr. Manhattan. Open source under MIT License.</p>
                <p style="margin-top: 10px;">
                  <a href="https://github.com/guzus/dr-manhattan">GitHub</a> • 
                  <a href="https://github.com/guzus/dr-manhattan/issues">Issues</a>
                </p>
              </footer>
            </div>

            <script>
              function copyCommand() {
                const command = "pip install dr-manhattan";
                navigator.clipboard.writeText(command).then(() => {
                  const btn = document.querySelector('.copy-btn');
                  const originalText = btn.textContent;
                  btn.textContent = 'Copied!';
                  btn.style.background = 'var(--accent-blue)';
                  btn.style.color = '#000';
                  setTimeout(() => {
                    btn.textContent = originalText;
                    btn.style.background = 'transparent';
                    btn.style.color = 'var(--accent-blue)';
                  }, 2000);
                });
              }
            </script>
          </body>
          </html>
          EOF

      - name: Setup Pages
        uses: actions/configure-pages@v5

      - name: Upload artifact
        uses: actions/upload-pages-artifact@v3
        with:
          path: 'docs'

      - name: Deploy to GitHub Pages
        id: deployment
        uses: actions/deploy-pages@v4
